def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # {key: (value, write_time)}
    results = []

    for op in ops:
        op_type = op[0]
        t = op[1]
        key = op[2]

        # Remove expired entries
        expired_keys = [k for k, (v, write_time) in cache.items() if write_time + ttl <= t]
        for k in expired_keys:
            del cache[k]

        if op_type == 'put':
            value = op[3]

            # If key exists, remove it first (will be re-added at end for MRU)
            if key in cache:
                del cache[key]
            # If cache is full, evict LRU (first item in OrderedDict)
            elif len(cache) >= capacity:
                cache.popitem(last=False)

            # Add the new entry (becomes MRU)
            cache[key] = (value, t)

        elif op_type == 'get':
            if key in cache:
                value, write_time = cache[key]
                # Check if expired
                if write_time + ttl <= t:
                    results.append(-1)
                else:
                    results.append(value)
                    # Make it MRU by moving to end
                    cache.move_to_end(key)
            else:
                results.append(-1)

    return results

